import assert from 'node:assert/strict';
import test from 'node:test';
import { readFileSync } from 'node:fs';
import { assertionBytes, assertionDigest, canonicalJson, payloadHash, validateAssertion, validatePayload } from '../src/send-approval/canonical.ts';

// Copied from Home's shared vectors, not regenerated by the inbox implementation under test.
const vectors = JSON.parse(readFileSync(new URL('./fixtures/send-approval-vectors.json', import.meta.url), 'utf8'));
for (const vector of vectors.payloads) {
  test(`Home payload conformance: ${vector.name}`, () => {
    const payload = validatePayload(vector.payload);
    assert.equal(canonicalJson(vector.payload), vector.canonical);
    assert.equal(payloadHash(payload), vector.payloadHash);
  });
}
for (const vector of vectors.assertions) {
  test(`Home assertion conformance: ${vector.name}`, () => {
    const assertion = validateAssertion(vector.assertion);
    assert.equal(assertionBytes(assertion).toString('utf8'), vector.canonical);
    assert.equal(assertionDigest(assertion).toString('hex'), vector.bytesSha256);
  });
}
